	private log(message: string): void {
		console.log(message);
	}
	/**
	 * Stores content to a temporary file via the disk service.
	 */
	private async storeTempFile(
		content: string | ArrayBuffer | ArrayBufferView,
		extension: string,
		prefix: string,
		location: "system" | "project" = "system",
		messageUUID?: string
	): Promise<string> {
